{
  "ontology_name": "Core_Ontology",
  "version": "2.0",
  "language": "en",
  "source_type": "technical PDF",
  "source_title": "hypertherm_powermax30_air_service_manual_rev4_808850.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_power_supply",
        "name": "Power Supply",
        "description": "The power supply, where the pressure test gauge is connected and gas-line leak checks are performed.",
        "category": "power"
      },
      {
        "component_id": "comp_fan",
        "name": "Fan",
        "description": "The fan, which may affect the appearance of leaks during leak testing and is disconnected from J5 on the power board for that test.",
        "category": "cooling"
      },
      {
        "component_id": "comp_air_compressor",
        "name": "Air Compressor",
        "description": "The air compressor, checked for proper voltage when air pressure is low and replaced if low pressure persists after the checks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_torch",
        "name": "Torch",
        "description": "A different torch is installed to determine whether a low-pressure issue persists.",
        "category": "cutting"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid Valve",
        "description": "The solenoid valve has gas hoses connected to each side that are checked for leaks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_filter_bowl",
        "name": "Filter Bowl",
        "description": "The filter bowl is checked for leaks where it screws into the air filter assembly and where the drain hose connects.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_air_filter_assembly",
        "name": "Air Filter Assembly",
        "description": "The air filter assembly includes the filter bowl, whose threaded connection is checked for leaks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_drain_hose",
        "name": "Drain Hose",
        "description": "The drain hose connections at the filter bowl and the base of the power supply are checked for leaks.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_power_board",
        "name": "Power Board",
        "description": "The fan connects to J5 on the power board and is disconnected during the leak test, then reconnected before system use.",
        "category": "electrical"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-Driver Board",
        "description": "The compressor-driver board is referenced in the procedure for checking diagnostic LED D5 when air pressure is low.",
        "category": "electrical"
      },
      {
        "component_id": "comp_led_d5",
        "name": "Diagnostic LED (D5)",
        "description": "A diagnostic LED on the compressor-driver board, referenced for a check when air pressure is low.",
        "category": "diagnostic"
      }
    ],
    "Symptom": [],
    "FailureMode": [],
    "CorrectiveAction": [],
    "ErrorCode": []
  },
  "relations": []
}
